import{_ as e,o as r,c as o,a0 as i}from"./chunks/framework.CV8GZ7IB.js";const m=JSON.parse('{"title":"Ecosystem","description":"How Microsphere Projects connects to the external technology stack","frontmatter":{"title":"Ecosystem","description":"How Microsphere Projects connects to the external technology stack","outline":[2,3]},"headers":[],"relativePath":"ecosystem.md","filePath":"ecosystem.md","lastUpdated":null}'),a={name:"ecosystem.md"};function s(d,t,n,c,h,p){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="ecosystem" tabindex="-1">Ecosystem <a class="header-anchor" href="#ecosystem" aria-label="Permalink to &quot;Ecosystem&quot;">​</a></h1><p>Microsphere is not a closed framework. Almost every project <strong>enhances an existing technology</strong> rather than replacing it. This page lists the integration points.</p><h2 id="technologies-we-integrate-with" tabindex="-1">Technologies we integrate with <a class="header-anchor" href="#technologies-we-integrate-with" aria-label="Permalink to &quot;Technologies we integrate with&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domain</th><th>External technology</th><th>Project</th></tr></thead><tbody><tr><td><strong>Core frameworks</strong></td><td>Spring Framework 4.3 – 7.0</td><td><a href="/projects/microsphere-spring">microsphere-spring</a></td></tr><tr><td></td><td>Spring Boot 2.0 – 4.1</td><td><a href="/projects/microsphere-spring-boot">microsphere-spring-boot</a></td></tr><tr><td></td><td>Spring Cloud Hoxton – 2025.x</td><td><a href="/projects/microsphere-spring-cloud">microsphere-spring-cloud</a></td></tr><tr><td><strong>Registry &amp; discovery</strong></td><td>Alibaba Nacos</td><td><a href="/projects/microsphere-nacos">microsphere-nacos</a></td></tr><tr><td></td><td>Netflix Eureka</td><td><a href="/projects/microsphere-netflix">microsphere-netflix</a></td></tr><tr><td></td><td>Consul / Zookeeper</td><td><a href="/projects/microsphere-spring-cloud">microsphere-spring-cloud</a></td></tr><tr><td></td><td>etcd</td><td><a href="/projects/microsphere-etcd">microsphere-etcd</a></td></tr><tr><td><strong>RPC &amp; gateway</strong></td><td>Apache Dubbo</td><td><a href="/projects/microsphere-dubbo">microsphere-dubbo</a></td></tr><tr><td></td><td>Spring Cloud Gateway (WebFlux / MVC)</td><td><a href="/projects/microsphere-gateway">microsphere-gateway</a></td></tr><tr><td></td><td>OpenFeign</td><td><a href="/projects/microsphere-spring-cloud">microsphere-spring-cloud</a></td></tr><tr><td><strong>Data access</strong></td><td>MyBatis</td><td><a href="/projects/microsphere-mybatis">microsphere-mybatis</a></td></tr><tr><td></td><td>Hibernate ORM 5.0 – 7.3</td><td><a href="/projects/microsphere-hibernate">microsphere-hibernate</a></td></tr><tr><td></td><td>Alibaba Druid</td><td><a href="/projects/microsphere-alibaba-druid">microsphere-alibaba-druid</a></td></tr><tr><td></td><td>P6Spy</td><td><a href="/projects/microsphere-spring">microsphere-spring</a></td></tr><tr><td><strong>Caching</strong></td><td>Spring Data Redis 2.1 – 3.5</td><td><a href="/projects/microsphere-redis">microsphere-redis</a></td></tr><tr><td></td><td>Apache Kafka (Redis replication)</td><td><a href="/projects/microsphere-redis">microsphere-redis</a></td></tr><tr><td><strong>Resilience</strong></td><td>Alibaba Sentinel</td><td><a href="/projects/microsphere-alibaba-sentinel">microsphere-alibaba-sentinel</a></td></tr><tr><td></td><td>Resilience4j 1.3 – 2.4</td><td><a href="/projects/microsphere-resilience4j">microsphere-resilience4j</a></td></tr><tr><td><strong>Observability</strong></td><td>Micrometer</td><td><a href="/projects/microsphere-observability">microsphere-observability</a></td></tr><tr><td></td><td>Prometheus</td><td><a href="/projects/microsphere-observability">microsphere-observability</a></td></tr><tr><td></td><td>OpenTelemetry Instrumentation BOM</td><td><a href="/projects/microsphere-observability">microsphere-observability</a></td></tr><tr><td><strong>Logging</strong></td><td>JUL / Log4j / Log4j2 / Logback / SLF4J</td><td><a href="/projects/microsphere-logging">microsphere-logging</a></td></tr><tr><td><strong>Web container</strong></td><td>Apache Tomcat</td><td><a href="/projects/microsphere-tomcat">microsphere-tomcat</a></td></tr><tr><td><strong>Enterprise specs</strong></td><td>Java EE / Jakarta EE / MicroProfile</td><td><a href="/projects/microsphere-java-enterprise">EE</a> · <a href="/projects/microsphere-jakarta">Jakarta</a> · <a href="/projects/microsphere-microprofile">MicroProfile</a></td></tr><tr><td><strong>Dependency injection</strong></td><td>Google Guice</td><td><a href="/projects/microsphere-spring">microsphere-spring</a></td></tr><tr><td><strong>Cloud platforms</strong></td><td>AWS (availability zone discovery)</td><td><a href="/projects/microsphere-multiactive">microsphere-multiactive</a></td></tr></tbody></table><h2 id="how-we-differ-from-other-enhancement-libraries" tabindex="-1">How we differ from other enhancement libraries <a class="header-anchor" href="#how-we-differ-from-other-enhancement-libraries" aria-label="Permalink to &quot;How we differ from other enhancement libraries&quot;">​</a></h2><p>Microsphere is positioned as an <strong>additive enhancement, never a replacement</strong>. Three defining traits:</p><ol><li><strong>Zero intrusion</strong> — most capabilities weave in through interception pipelines, auto-configuration and events. A single <code>@EnableP6DataSource</code> annotation wraps every DataSource bean for SQL tracing.</li><li><strong>Trimmable</strong> — each Maven module can be adopted independently, with no forced transitive baggage.</li><li><strong>Long-lifecycle compatibility</strong> — a compatibility shim keeps one codebase working across Spring Boot 2.x to 4.x, so upgrades never require a fork.</li></ol><h2 id="publishing" tabindex="-1">Publishing <a class="header-anchor" href="#publishing" aria-label="Permalink to &quot;Publishing&quot;">​</a></h2><ul><li>All artifacts are published to <strong>Maven Central</strong> under the Group ID <code>io.github.microsphere-projects</code></li><li>Since <code>microsphere-build</code> 0.2.0, publishing goes through the Central Publisher Portal (OSSRH reached end of life on 2025-06-30)</li><li>Every repository runs Maven Build and Codecov workflows</li></ul><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>Each sub-project ships bilingual documentation (English by default, Chinese under <code>zh/</code>), organised per release branch:</p><table tabindex="0"><thead><tr><th>Resource</th><th>Location</th></tr></thead><tbody><tr><td>In-repo user guide</td><td><code>docs/user-guide/</code> · <code>docs/developer-guide/</code></td></tr><tr><td>AI-assisted Q&amp;A</td><td>The corresponding DeepWiki and Zread spaces</td></tr><tr><td>JavaDoc</td><td>javadoc.io (published per module)</td></tr><tr><td>Wiki</td><td>Each repository&#39;s GitHub Wiki</td></tr></tbody></table>',12)])])}const g=e(a,[["render",s]]);export{m as __pageData,g as default};
